# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="system-ui, -apple-system, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <rect x="10" y="10" width="680" height="34" fill="#065f46" rx="8"/>\n  <text x="350" y="32" fill="#ffffff" font-size="13" font-weight="bold" text-anchor="middle">İMRAN AİLESİ, KUTLU ANNE HZ. MERYEM VE HZ. İSA\'NIN MUCİZEVİ DOĞUMU</text>\n\n  <rect x="15" y="54" width="210" height="190" fill="#ecfdf5" stroke="#10b981" stroke-width="1.5" rx="8"/>\n  <rect x="15" y="54" width="210" height="26" fill="#059669" rx="6"/>\n  <text x="120" y="71" fill="#ffffff" font-size="10.5" font-weight="bold" text-anchor="middle">1. İMRAN AİLESİ VE HZ. MERYEM</text>\n  <text x="25" y="95" fill="#064e3b" font-size="9.5" font-weight="bold">• Mensup Olduğu Aile:</text>\n  <text x="29" y="109" fill="#1e293b" font-size="9">İmran ailesi (Âl-i İmran)</text>\n  <text x="25" y="127" fill="#064e3b" font-size="9.5" font-weight="bold">• Annesi Hanne\'nin Adaklığı:</text>\n  <text x="29" y="141" fill="#1e293b" font-size="9">Doğacak çocuğunu Beytülmakdis\'e</text>\n  <text x="29" y="154" fill="#1e293b" font-size="9">(Mescid-i Aksa\'ya) hizmete adadı.</text>\n  <text x="25" y="172" fill="#064e3b" font-size="9.5" font-weight="bold">• Himaye Eden Peygamber:</text>\n  <text x="29" y="186" fill="#1e293b" font-size="9">Teyzesinin eşi Hz. Zekeriyya (as)</text>\n  <text x="25" y="204" fill="#064e3b" font-size="9.5" font-weight="bold">• Kur\'an\'daki Konumu:</text>\n  <text x="29" y="218" fill="#1e293b" font-size="9">İffeti, takvası ve ihlasıyla âlemlerin</text>\n  <text x="29" y="231" fill="#1e293b" font-size="9">kadınlarına üstün kılınmıştır.</text>\n\n  <rect x="240" y="54" width="220" height="190" fill="#f0f9ff" stroke="#0ea5e9" stroke-width="1.5" rx="8"/>\n  <rect x="240" y="54" width="220" height="26" fill="#0284c7" rx="6"/>\n  <text x="350" y="71" fill="#ffffff" font-size="10.5" font-weight="bold" text-anchor="middle">2. MUCİZEVİ DOĞUM VE BEŞİKTE KONUŞMA</text>\n  <text x="250" y="95" fill="#0c4a6e" font-size="9.5" font-weight="bold">• İlahi Müjde ve Yaratılış:</text>\n  <text x="254" y="109" fill="#1e293b" font-size="9">Cebrail (as) tarafından babasız bir</text>\n  <text x="254" y="122" fill="#1e293b" font-size="9">erkek çocuk müjdelendi. Hz. Âdem\'i</text>\n  <text x="254" y="135" fill="#1e293b" font-size="9">anasız-babasız yaratan Allah (cc),</text>\n  <text x="254" y="148" fill="#1e293b" font-size="9">Hz. İsa\'yı da babasız yarattı.</text>\n  <text x="250" y="166" fill="#0c4a6e" font-size="9.5" font-weight="bold">• Beşikteki Mucize (Meryem, 30):</text>\n  <text x="254" y="180" fill="#0369a1" font-size="9" font-style="italic">"Şüphesiz ben Allah\'ın kuluyum.</text>\n  <text x="254" y="193" fill="#0369a1" font-size="9" font-style="italic">O bana kitap verdi ve beni bir</text>\n  <text x="254" y="206" fill="#0369a1" font-size="9" font-style="italic">peygamber yaptı."</text>\n  <text x="254" y="222" fill="#1e293b" font-size="8.5">Böylece annesinin iffetini temize çıkardı.</text>\n\n  <rect x="475" y="54" width="210" height="190" fill="#fefce8" stroke="#eab308" stroke-width="1.5" rx="8"/>\n  <rect x="475" y="54" width="210" height="26" fill="#ca8a04" rx="6"/>\n  <text x="580" y="71" fill="#ffffff" font-size="10.5" font-weight="bold" text-anchor="middle">3. KUR\'AN\'DA HZ. İSA (AS)</text>\n  <text x="485" y="95" fill="#713f12" font-size="9.5" font-weight="bold">• Gönderildiği Kavim ve Kitap:</text>\n  <text x="489" y="109" fill="#1e293b" font-size="9">İsrailoğulları\'na gönderildi; kendisine</text>\n  <text x="489" y="122" fill="#1e293b" font-size="9">ilahi kitap olarak İncil indirildi.</text>\n  <text x="485" y="140" fill="#713f12" font-size="9.5" font-weight="bold">• Ulü\'l-Azm ve Müjdeleyici:</text>\n  <text x="489" y="154" fill="#1e293b" font-size="9">Beş büyük ulü\'l-azm peygamberden</text>\n  <text x="489" y="167" fill="#1e293b" font-size="9">biridir; kendisinden sonra "Ahmet"</text>\n  <text x="489" y="180" fill="#1e293b" font-size="9">isminde elçi geleceğini müjdeledi (Saff, 6).</text>\n  <text x="485" y="198" fill="#713f12" font-size="9.5" font-weight="bold">• Anlatıldığı Sureler:</text>\n  <text x="489" y="212" fill="#1e293b" font-size="9">Başta Âl-i İmran, Mâide ve Meryem</text>\n  <text x="489" y="225" fill="#1e293b" font-size="9">olmak üzere toplam 15 surede geçer.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="system-ui, -apple-system, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <rect x="10" y="10" width="680" height="32" fill="#1e40af" rx="8"/>\n  <text x="350" y="30" fill="#ffffff" font-size="13" font-weight="bold" text-anchor="middle">HZ. İSA\'NIN (AS) MUCİZELERİ (ALLAH\'IN İZNİYLE) VE HAVARİLER</text>\n\n  <rect x="15" y="50" width="215" height="62" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5" rx="8"/>\n  <text x="122" y="68" fill="#1e3a8a" font-size="10" font-weight="bold" text-anchor="middle">1. BEŞİKTEYKEN KONUŞMASI</text>\n  <text x="122" y="84" fill="#1e293b" font-size="9" text-anchor="middle">Henüz bebekken konuşarak Allah\'ın</text>\n  <text x="122" y="98" fill="#1e293b" font-size="9" text-anchor="middle">kulu ve peygamberi olduğunu bildirdi.</text>\n\n  <rect x="242" y="50" width="215" height="62" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5" rx="8"/>\n  <text x="350" y="68" fill="#1e3a8a" font-size="10" font-weight="bold" text-anchor="middle">2. ÇAMURDAN KUŞUN CANLANMASI</text>\n  <text x="350" y="84" fill="#1e293b" font-size="9" text-anchor="middle">Çamurdan kuş şekli yapıp üfleyince</text>\n  <text x="350" y="98" fill="#1e293b" font-size="9" text-anchor="middle">Allah\'ın izniyle kuş canlandı.</text>\n\n  <rect x="470" y="50" width="215" height="62" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5" rx="8"/>\n  <text x="577" y="68" fill="#1e3a8a" font-size="10" font-weight="bold" text-anchor="middle">3. HASTALARI İYİLEŞTİRMESİ</text>\n  <text x="577" y="84" fill="#1e293b" font-size="9" text-anchor="middle">Doğuştan kör olanları (ekmeh) ve</text>\n  <text x="577" y="98" fill="#1e293b" font-size="9" text-anchor="middle">alacalıları (ebras) iznillah iyileştirdi.</text>\n\n  <rect x="15" y="122" width="215" height="62" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5" rx="8"/>\n  <text x="122" y="140" fill="#1e3a8a" font-size="10" font-weight="bold" text-anchor="middle">4. ÖLÜLERİ DİRİLTMESİ</text>\n  <text x="122" y="156" fill="#1e293b" font-size="9" text-anchor="middle">Yüce Allah\'ın izniyle ölüleri</text>\n  <text x="122" y="170" fill="#1e293b" font-size="9" text-anchor="middle">dirilterek kudret delili gösterdi.</text>\n\n  <rect x="242" y="122" width="215" height="62" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5" rx="8"/>\n  <text x="350" y="140" fill="#1e3a8a" font-size="10" font-weight="bold" text-anchor="middle">5. GİZLENENLERİ HABER VERMESİ</text>\n  <text x="350" y="156" fill="#1e293b" font-size="9" text-anchor="middle">İnsanların evlerinde yediklerini ve</text>\n  <text x="350" y="170" fill="#1e293b" font-size="9" text-anchor="middle">biriktirdiklerini haber verdi.</text>\n\n  <rect x="470" y="122" width="215" height="62" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5" rx="8"/>\n  <text x="577" y="140" fill="#1e3a8a" font-size="10" font-weight="bold" text-anchor="middle">6. GÖKTEN MÂİDE (SOFRA) İNMESİ</text>\n  <text x="577" y="156" fill="#1e293b" font-size="9" text-anchor="middle">Havarilerin isteği ve Hz. İsa\'nın</text>\n  <text x="577" y="170" fill="#1e293b" font-size="9" text-anchor="middle">duasıyla gökten sofra indirildi.</text>\n\n  <rect x="15" y="194" width="670" height="54" fill="#fef3c7" stroke="#d97706" stroke-width="1.5" rx="8"/>\n  <text x="350" y="214" fill="#92400e" font-size="10.5" font-weight="bold" text-anchor="middle">TEVHİD DAVETİ VE SAMİMİ YARDIMCILAR: HAVARİLER</text>\n  <text x="350" y="232" fill="#1e293b" font-size="9.5" text-anchor="middle">30 yaşında peygamber olan Hz. İsa, Tevrat\'ı tasdik edip kavmini yalnız Allah\'a kulluğa çağırmış; ona iman edip destekleyenlere "Havariler" denmiştir.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="system-ui, -apple-system, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <rect x="10" y="10" width="680" height="34" fill="#7c2d12" rx="8"/>\n  <text x="350" y="32" fill="#ffffff" font-size="13" font-weight="bold" text-anchor="middle">HZ. İSA\'NIN ALLAH KATINA YÜKSELTİLMESİ VE SONRASINDAKİ DEĞİŞİMLER</text>\n\n  <rect x="15" y="56" width="320" height="188" fill="#ecfdf5" stroke="#059669" stroke-width="1.5" rx="8"/>\n  <rect x="15" y="56" width="320" height="28" fill="#047857" rx="6"/>\n  <text x="175" y="75" fill="#ffffff" font-size="11" font-weight="bold" text-anchor="middle">KUR\'AN\'A GÖRE HZ. İSA\'NIN AKIBETİ</text>\n  <text x="27" y="100" fill="#064e3b" font-size="9.5" font-weight="bold">• Tuzakların Boşa Çıkarılması:</text>\n  <text x="31" y="115" fill="#1e293b" font-size="9">İnkârcı Yahudi ileri gelenleri Hz. İsa\'yı</text>\n  <text x="31" y="129" fill="#1e293b" font-size="9">öldürmek için tuzak kurdu; ancak Allah (cc)</text>\n  <text x="31" y="143" fill="#1e293b" font-size="9">elçisini korudu.</text>\n  <text x="27" y="164" fill="#064e3b" font-size="9.5" font-weight="bold">• Nisa Suresi 157-158. Ayetler:</text>\n  <text x="31" y="179" fill="#047857" font-size="9.5" font-style="italic">"Onu öldürmediler ve asmadılar (çarmıha</text>\n  <text x="31" y="193" fill="#047857" font-size="9.5" font-style="italic">germediler), fakat onlara öyle göründü..."</text>\n  <text x="27" y="214" fill="#064e3b" font-size="9.5" font-weight="bold">• Allah Katına Yükseltilme:</text>\n  <text x="31" y="229" fill="#1e293b" font-size="9">Allah (cc) Hz. İsa\'yı kendi katına yükseltmiştir.</text>\n\n  <rect x="365" y="56" width="320" height="188" fill="#fef2f2" stroke="#dc2626" stroke-width="1.5" rx="8"/>\n  <rect x="365" y="56" width="320" height="28" fill="#b91c1c" rx="6"/>\n  <text x="525" y="75" fill="#ffffff" font-size="11" font-weight="bold" text-anchor="middle">HZ. İSA SONRASI TARİHSEL KIRILMALAR</text>\n  <text x="377" y="100" fill="#7f1d1d" font-size="9.5" font-weight="bold">• Pavlus ve Tevhidden Sapma:</text>\n  <text x="381" y="115" fill="#1e293b" font-size="9">Putperest kültürlerin etkisi ve Pavlus\'un</text>\n  <text x="381" y="129" fill="#1e293b" font-size="9">öncülüğünde tevhid inancından uzaklaşılarak</text>\n  <text x="381" y="143" fill="#b91c1c" font-size="9" font-weight="bold">teslis (üçleme: Baba-Oğul-Kutsal Ruh)</text>\n  <text x="381" y="157" fill="#1e293b" font-size="9">inancı ortaya çıktı.</text>\n  <text x="377" y="177" fill="#7f1d1d" font-size="9.5" font-weight="bold">• IV. Yüzyıl ve İznik Konsili (325):</text>\n  <text x="381" y="192" fill="#1e293b" font-size="9">Hristiyanlık Roma İmparatorluğu\'nun resmî dini</text>\n  <text x="381" y="206" fill="#1e293b" font-size="9">oldu; farklı İnciller arasından 4 İncil</text>\n  <text x="381" y="220" fill="#7f1d1d" font-size="9" font-weight="bold">(Matta, Markos, Luka, Yuhanna)</text>\n  <text x="381" y="234" fill="#1e293b" font-size="9">resmen kabul edildi.</text>\n</svg>']

def uygula(v):
    for i, s in enumerate(SVGS):
        if i < len(v.get('bolumler', [])):
            v['bolumler'][i]['gorsel'] = s
